INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre) VALUES ('d0be2301-dc5c-56ec-8d37-eabdcedb6424', '95219bb3-c61b-5d04-b066-fb7c6254ffdf', 1, 'Convocatoria · CFE-0004-CACOT-0012-2026', '<p>COMISION FEDERAL DE ELECTRICIDAD</p>
<p>DIRECCION DE ADMINISTRACION</p>
<p>SUBDIRECCION DE CONTRATACION Y SERVICIOS</p>
<p>COORDINACION DE CONTRATACIONES DE OBRA Y SERVICIOS RELACIONADOS</p>
<p>GERENCIA DE CONTRATACIONES DE OBRA</p>
<p>CONVOCATORIA AL CONCURSO ABIERTO DE CARACTER INTERNACIONAL BAJO LA COBERTURA DE LOS TRATADOS</p>
<p>NUMERO CFE-0004-CACOT-0012-2026</p>
<p>Con fundamento en el Artículo 134 de la Constitución Política de los Estados Unidos Mexicanos, y en apego a la Disposición 73 de las “Disposiciones Generales en Materia de Adquisiciones, Arrendamientos, Contratación de Servicios y Ejecución de Obras de la Comisión Federal de Electricidad”, la Gerencia de Contrataciones de Obra, convoca a los interesados a participar en el Concurso Abierto de Carácter Internacional bajo la cobertura de los tratados Número CFE-0004-CACOT-00012-2026, para la contratación de los trabajos de la 376 SLT Suministro de Energía Eléctrica en Tabasco.</p>
<p>Los interesados podrán consultar el Pliego de Requisitos y Registrar su interés en participar a través del Sistema Electrónico de Contrataciones (Micrositio de Concursos) en la dirección electrónica: http://msc.cfe.mx/aplicaciones/NCFE/concursos.</p>
<p>El procedimiento de contratación se llevará a cabo con la siguiente programación:</p>
<table><tbody><tr><th scope="row">Visita al Sitio de los trabajos:</th><td colspan="2">Se efectuarán a las 09:30 horas, los días 23 y 24 de noviembre de 2026, siendo los puntos de reunión de acuerdo con lo establecido en el Anexo 3 de la Sección 1 del Pliego de Requisitos.</td></tr><tr><th scope="row">Sesión de aclaraciones:</th><td>30 de noviembre de 2026 10:00 horas</td><td rowspan="4">Los citados actos se llevarán a cabo a través del Sistema Electrónico de Contrataciones (Micrositio de Concursos)</td></tr><tr><th scope="row">Presentación de Ofertas y Apertura de Ofertas Técnicas:</th><td>11 de enero de 2027 10:00 horas</td></tr><tr><th scope="row">Apertura de Ofertas Económicas:</th><td>21 de enero de 2027 12:00 horas</td></tr><tr><th scope="row">Acto de Fallo:</th><td>28 de enero de 2027 12:00 horas</td></tr></tbody></table>
<p>El Area Contratante que publica la presente convocatoria es la Gerencia de Contrataciones de Obra de la CFE, con domicilio en Río Mississippi, número 71, 1er Piso, Colonia Cuauhtémoc, Alcaldía Cuauhtémoc, Código Postal 06500, Ciudad de México. El personal de contacto es el C.P. Antonio González Barrascout, Gerente y el Mtro. Héctor Omar Leal Nava, Jefe de Departamento, con correo electrónico omar.leal@cfe.mx.</p>
<p>ATENTAMENTE</p>
<p>CIUDAD DE MEXICO, A 3 DE NOVIEMBRE DE 2026.</p>
<p>AGENTE CONTRATANTE No. O1A0401</p>
<p>MTRO. HECTOR OMAR LEAL NAVA</p>
<p>RUBRICA.</p>
<p>(R.- 581914)</p>', 'convocatoria', 'CFE-0004-CACOT-0012-2026', '376 SLT Suministro de energía eléctrica en Tabasco');
