INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre) VALUES ('ec233c77-9478-5dd7-ad61-eba6cfe79462', '47db1d40-c33b-50c8-b05e-cbf7c7750477', 1, 'Convocatoria · CFE-0700-CASAN-0049-2026', '<p>COMISION FEDERAL DE ELECTRICIDAD A RUEGO Y ENCARGO</p>
<p>COORDINACION REGIONAL DE PRODUCCION NORTE</p>
<p>RESUMEN DE CONVOCATORIA</p>
<p>Con fundamento en el Artículo 134 de la Constitución Política de los Estados Unidos Mexicanos, Artículo 80 y 82, de la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad, en las disposiciones 2 fracción I, inciso b), 4 fracción XI, 30 fracción I inciso a), 33 fracción IV y VIII, 31, 37 fracción I y 56 fracción III y IV de las Disposiciones Generales en Materia de Adquisiciones, Arrendamientos, Contratación de Servicios y Ejecución de Obras de la Comisión Federal de Electricidad y sus Empresas Productivas Subsidiarias y sus modificaciones publicadas en el Diario Oficial de la Federación el día 31 de enero de 2022, se convoca a los interesados a participar en el Concurso Abierto Nacional, cuya Convocatoria contiene el Pliego de Requisitos disponible para consulta en la siguiente dirección: https://msc.cfe.mx., a partir de la fecha de su publicación en Micrositio de Concursos, de conformidad con lo siguiente:</p>
<table><tbody><tr><th scope="row">Número de Procedimiento</th><td>CFE-0700-CASAN-0049-2026</td></tr><tr><th scope="row">Objeto de la Contratación</th><td>“Mantenimiento a Válvulas de Estrangulamiento de la Turbina de las Unidades 3 y 4 de la Central Termoeléctrica Altamira”</td></tr><tr><th scope="row">Fecha de publicación en Micrositio</th><td>30/10/2026</td></tr><tr><th scope="row">Sesión de aclaraciones</th><td>03/11/2026 10:30 horas</td></tr><tr><th scope="row">Apertura de Ofertas Técnicas</th><td>09/11/2026 10:00 horas</td></tr><tr><th scope="row">Resultado Técnico y Apertura Ofertas Económicas</th><td>11/11/2026 10:35 horas</td></tr><tr><th scope="row">Notificación de Fallo</th><td>12/11/2026 11:00 horas</td></tr></tbody></table>
<p>MONTERREY, NUEVO LEON, A 3 DE NOVIEMBRE DE 2026.</p>
<p>ENCARGADO DEL DESPACHO DEL DEPARTAMENTO REGIONAL DE CONTRATACION Y OBRA PUBLICA</p>
<p>ING. JULIO ANTONIO GONZALEZ VILLARREAL</p>
<p>FIRMA ELECTRONICA.</p>
<p>(R.- 581959)</p>', 'convocatoria', 'CFE-0700-CASAN-0049-2026', 'Válvulas de estrangulamiento de las unidades 3 y 4 de la CT Altamira');
